import re

_LOCAL = re.compile(r"^[A-Za-z0-9._%+-]+$")
_DOMAIN = re.compile(r"^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$")


def is_valid_email(address: str) -> bool:
    """Return True if `address` looks like a valid email address."""
    if not isinstance(address, str) or len(address) > 254 or address.count("@") != 1:
        return False
    local, domain = address.split("@")
    return bool(local) and bool(_LOCAL.match(local)) and bool(_DOMAIN.match(domain))

